import * as React from "react"

function GradientCard({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="gradient-card"
      className={className}
      {...props}
    >
      <div className="bg-gray-900 h-screen flex flex-col justify-center items-center">
          <div className="bg-gradient-to-r from-purple-600 to-pink-600 rounded-lg shadow-lg p-8">
              <h1 className="text-4xl font-bold text-white mb-4">
                  Tailwind CSS
              </h1>
              <p className="text-lg text-white mb-8">
                  A utility-first CSS framework for rapidly building custom designs.
              </p>
              <a href="#" className="bg-white hover200 text-purple-600 font-bold py-2 px-4 rounded">
                  Get started
              </a>
          </div>
      </div>
    </div>
  )
}

export { GradientCard }
